import { Fragment, options, createContext, toChildArray, cloneElement } from 'preact';
import { diff, commitRoot } from '../../src/diff/index';
import { assign } from '../../src/util';
import { createVNode } from '../../src/create-element';

const RAF_TIMEOUT = 100;

function invokeOrReturn(arg, f) {
	return typeof f == 'function' ? f(arg) : f;
}

function argsChanged(oldArgs, newArgs) {
	return (
		!oldArgs ||
		oldArgs.length !== newArgs.length ||
		newArgs.some((arg, index) => arg !== oldArgs[index])
	);
}

function hashMask(s) {
	let h = 0,
		i = s.length;
	while (i > 0) {
		h = ((h << 5) - h + s.charCodeAt(--i)) | 0;
	}
	return h;
}

class Dispatcher {
	constructor() {
		this.currentIndex = 0;
		this.currentComponent = null;
		this.previousComponent = null;
		this.currentHook = 0;
		this.afterPaintEffects = [];
		this.empty = [];
		this.prevRaf = undefined;
		this.hasRaf = typeof requestAnimationFrame == 'function';
		this.rafTimeout = RAF_TIMEOUT;
		this.oldBeforeDiff = options._diff;
		this.oldBeforeRender = options._render;
		this.oldAfterDiff = options.diffed;
		this.oldCommit = options._commit;
		this.oldBeforeUnmount = options.unmount;
		this.fragmentType = Fragment;
		this.rerenderQueue = [];
		this.prevDebounce = undefined;
		this.rerenderCount = 0;
		this.providerSubs = new Map();
		this.contextSeq = 0;
		this.lastCaughtError = null;
		this.errorInfoSnapshot = null;
		this.childScratch = [];
		this.pendingChildValues = [];
		this.siblingCursor = 0;
		this.cloneBuffer = null;
		this.flattenDepth = 0;
	}

	install() {
		this.currentComponent = this.currentComponent || null;
		options._diff = vnode => this.handleBeforeDiff(vnode);
		options._render = vnode => this.handleBeforeRender(vnode);
		options.diffed = vnode => this.handleDiffed(vnode);
		options._commit = (vnode, commitQueue) =>
			this.handleCommit(vnode, commitQueue);
		options.unmount = vnode => this.handleUnmount(vnode);
		options._dispatcher = this;
		if (options._catchError) {
			options._catchError._dispatcher = this;
		}
		if (createContext) {
			createContext._dispatcher = this;
		}
		if (toChildArray) {
			toChildArray._dispatcher = this;
		}
		if (cloneElement) {
			cloneElement._dispatcher = this;
		}
	}

	handleBeforeDiff(vnode) {
		if (
			typeof vnode.type === 'function' &&
			!vnode._mask &&
			vnode.type !== this.fragmentType
		) {
			let mask = '';
			if (vnode._parent && vnode._parent._mask) {
				mask = vnode._parent._mask;
			}
			let index = 0;
			if (vnode._parent && vnode._parent._children) {
				index = vnode._parent._children.indexOf(vnode);
			}
			vnode._mask = mask + index;
		} else if (!vnode._mask) {
			if (vnode._parent && vnode._parent._mask) {
				vnode._mask = vnode._parent._mask;
			} else {
				vnode._mask = '';
			}
		}
		this.currentComponent = null;
		if (this.oldBeforeDiff) {
			this.oldBeforeDiff(vnode);
		}
	}

	handleBeforeRender(vnode) {
		if (this.oldBeforeRender) {
			this.oldBeforeRender(vnode);
		}
		this.currentComponent = vnode._component;
		this.currentIndex = 0;
		this.currentHook = 0;
		const hooks = this.currentComponent.__hooks;
		if (hooks) {
			if (this.previousComponent === this.currentComponent) {
				this.recycleHookState(hooks);
			} else {
				hooks._pendingEffects.forEach(hook => this.invokeCleanup(hook));
				hooks._pendingEffects.forEach(hook => this.invokeEffect(hook));
				hooks._pendingEffects = [];
			}
		}
		this.previousComponent = this.currentComponent;
	}

	recycleHookState(hooks) {
		hooks._pendingEffects = [];
		if (this.currentComponent) {
			this.currentComponent._renderCallbacks = [];
		}
		hooks._list.forEach(hookItem => {
			if (hookItem._nextValue) {
				hookItem._value = hookItem._nextValue;
			}
			hookItem._pendingValue = this.empty;
			hookItem._nextValue = undefined;
			hookItem._pendingArgs = undefined;
		});
	}

	handleDiffed(vnode) {
		if (this.oldAfterDiff) {
			this.oldAfterDiff(vnode);
		}
		const c = vnode._component;
		if (c && c.__hooks) {
			if (c.__hooks._pendingEffects.length) {
				this.afterPaint(this.queuePaintComponent(c));
			}
			c.__hooks._list.forEach(hookItem => {
				if (hookItem._pendingArgs) {
					hookItem._args = hookItem._pendingArgs;
				}
				if (hookItem._pendingValue !== this.empty) {
					hookItem._value = hookItem._pendingValue;
				}
				hookItem._pendingArgs = undefined;
				hookItem._pendingValue = this.empty;
			});
		}
		this.previousComponent = null;
		this.currentComponent = null;
	}

	handleCommit(vnode, commitQueue) {
		const owner = this.currentComponent;
		commitQueue.some(component => {
			try {
				component._renderCallbacks.forEach(cb => this.invokeCleanup(cb));
				component._renderCallbacks = component._renderCallbacks.filter(cb =>
					cb._value ? this.invokeEffect(cb) : true
				);
			} catch (e) {
				commitQueue.some(c => {
					if (c._renderCallbacks) c._renderCallbacks = [];
				});
				commitQueue = [];
				options._catchError(e, component._vnode);
			}
		});
		if (this.oldCommit) {
			this.oldCommit(vnode, commitQueue);
		}
		this.currentComponent = owner;
	}

	handleUnmount(vnode) {
		const owner = this.currentComponent;
		if (this.oldBeforeUnmount) {
			this.oldBeforeUnmount(vnode);
		}
		const c = vnode._component;
		if (c && c.__hooks) {
			let hasErrored;
			c.__hooks._list.forEach(s => {
				try {
					this.invokeCleanup(s);
				} catch (e) {
					hasErrored = e;
				}
			});
			c.__hooks = undefined;
			if (hasErrored) {
				options._catchError(hasErrored, c._vnode);
			}
		}
		this.currentComponent = owner;
	}

	getHookState(index, type) {
		const component = this.currentComponent;
		const hookType = this.currentHook || type;
		if (options._hook) {
			options._hook(component, index, hookType);
		}
		this.currentHook = 0;
		let hooks = component.__hooks;
		if (!hooks) {
			hooks = {
				_list: [],
				_pendingEffects: []
			};
			component.__hooks = hooks;
		}
		if (index >= hooks._list.length) {
			hooks._list.push({ _pendingValue: this.empty });
		}
		return hooks._list[index];
	}

	useState(initialState) {
		const owner = this.currentComponent;
		this.currentHook = 1;
		const result = this.useReducer(invokeOrReturn, initialState);
		this.currentComponent = owner;
		return result;
	}

	useReducer(reducer, initialState, init) {
		const hookState = this.getHookState(this.currentIndex++, 2);
		hookState._reducer = reducer;
		if (!hookState._component) {
			let initial;
			if (!init) {
				initial = invokeOrReturn(undefined, initialState);
			} else {
				initial = init(initialState);
			}
			hookState._value = [
				initial,
				action => {
					const currentValue = hookState._nextValue
						? hookState._nextValue[0]
						: hookState._value[0];
					const nextValue = hookState._reducer(currentValue, action);
					if (currentValue !== nextValue) {
						hookState._nextValue = [nextValue, hookState._value[1]];
						hookState._component.setState({});
					}
				}
			];
			hookState._component = this.currentComponent;
			if (!this.currentComponent._hasScuFromHooks) {
				this.currentComponent._hasScuFromHooks = true;
				const prevScu = this.currentComponent.shouldComponentUpdate;
				this.currentComponent.shouldComponentUpdate = function(p, s, c) {
					if (!hookState._component.__hooks) return true;
					const stateHooks = hookState._component.__hooks._list.filter(
						x => x._component
					);
					const allHooksEmpty = stateHooks.every(x => !x._nextValue);
					if (allHooksEmpty) {
						return prevScu ? prevScu.call(this, p, s, c) : true;
					}
					let shouldUpdate = false;
					stateHooks.forEach(hookItem => {
						if (hookItem._nextValue) {
							const currentValue = hookItem._value[0];
							hookItem._value = hookItem._nextValue;
							hookItem._nextValue = undefined;
							if (currentValue !== hookItem._value[0]) shouldUpdate = true;
						}
					});
					return shouldUpdate
						? prevScu
							? prevScu.call(this, p, s, c)
							: true
						: false;
				};
			}
		}
		if (hookState._nextValue) {
			return hookState._nextValue;
		}
		return hookState._value;
	}

	useEffect(callback, args) {
		const state = this.getHookState(this.currentIndex++, 3);
		if (!options._skipEffects && argsChanged(state._args, args)) {
			state._value = callback;
			state._pendingArgs = args;
			this.currentComponent.__hooks._pendingEffects.push(state);
		}
	}

	useLayoutEffect(callback, args) {
		const state = this.getHookState(this.currentIndex++, 4);
		if (!options._skipEffects && argsChanged(state._args, args)) {
			state._value = callback;
			state._pendingArgs = args;
			this.currentComponent._renderCallbacks.push(state);
		}
	}

	useRef(initialValue) {
		const owner = this.currentComponent;
		this.currentHook = 5;
		const result = this.useMemo(() => ({ current: initialValue }), []);
		this.currentComponent = owner;
		return result;
	}

	useImperativeHandle(ref, createHandle, args) {
		const owner = this.currentComponent;
		this.currentHook = 6;
		this.useLayoutEffect(
			() => {
				if (typeof ref == 'function') {
					ref(createHandle());
					return () => ref(null);
				} else if (ref) {
					ref.current = createHandle();
					return () => (ref.current = null);
				}
			},
			args == null ? args : args.concat(ref)
		);
		this.currentComponent = owner;
	}

	useMemo(factory, args) {
		const owner = this.currentComponent;
		const state = this.getHookState(this.currentIndex++, 7);
		if (argsChanged(state._args, args)) {
			state._pendingValue = factory();
			state._pendingArgs = args;
			state._factory = factory;
			this.currentComponent = owner;
			return state._pendingValue;
		}
		this.currentComponent = owner;
		return state._value;
	}

	useCallback(callback, args) {
		const owner = this.currentComponent;
		this.currentHook = 8;
		const result = this.useMemo(() => callback, args);
		this.currentComponent = owner;
		return result;
	}

	useContext(context) {
		const provider = this.currentComponent.context[context._id];
		const state = this.getHookState(this.currentIndex++, 9);
		state._context = context;
		if (!provider) {
			return context._defaultValue;
		}
		if (state._value == null) {
			state._value = true;
			provider.sub(this.currentComponent);
		}
		return provider.props.value;
	}

	useDebugValue(value, formatter) {
		if (this.currentComponent && options.useDebugValue) {
			options.useDebugValue(formatter ? formatter(value) : value);
		} else if (options.useDebugValue) {
			options.useDebugValue(formatter ? formatter(value) : value);
		}
	}

	useErrorBoundary(cb) {
		const state = this.getHookState(this.currentIndex++, 10);
		const errState = this.useState();
		state._value = cb;
		if (!this.currentComponent.componentDidCatch) {
			this.currentComponent.componentDidCatch = (err, errorInfo) => {
				if (state._value) {
					state._value(err, errorInfo);
				}
				errState[1](err);
			};
		}
		return [
			errState[0],
			() => {
				errState[1](undefined);
			}
		];
	}

	useId() {
		const state = this.getHookState(this.currentIndex++, 11);
		if (!state._value) {
			const mask = this.currentComponent._vnode._mask;
			state._value = 'P' + hashMask(mask) + this.currentIndex;
		}
		return state._value;
	}

	invokeCleanup(hook) {
		const comp = this.currentComponent;
		let cleanup = hook._cleanup;
		if (typeof cleanup == 'function') {
			hook._cleanup = undefined;
			cleanup();
		}
		this.currentComponent = comp;
	}

	invokeEffect(hook) {
		const comp = this.currentComponent;
		hook._cleanup = hook._value();
		this.currentComponent = comp;
	}

	queuePaintComponent(component) {
		return this.afterPaintEffects.push(component);
	}

	shiftPaintComponent() {
		if (this.afterPaintEffects.length === 0) {
			return undefined;
		}
		return this.afterPaintEffects.shift();
	}

	hasPaintWork() {
		return this.afterPaintEffects.length > 0;
	}

	flushAfterPaintEffects() {
		if (!this.afterPaintEffects) {
			this.afterPaintEffects = [];
		}
		let component;
		while ((component = this.shiftPaintComponent())) {
			if (!component._parentDom || !component.__hooks) {
				continue;
			}
			try {
				component.__hooks._pendingEffects.forEach(hook =>
					this.invokeCleanup(hook)
				);
				component.__hooks._pendingEffects.forEach(hook =>
					this.invokeEffect(hook)
				);
				component.__hooks._pendingEffects = [];
			} catch (e) {
				component.__hooks._pendingEffects = [];
				options._catchError(e, component._vnode);
			}
		}
	}

	afterNextFrame(callback) {
		if (!this.afterPaintEffects) {
			this.afterPaintEffects = [];
		}
		const done = () => {
			clearTimeout(timeout);
			this.cancelPaintFrame(raf);
			setTimeout(callback);
		};
		const timeout = setTimeout(done, this.rafTimeout);
		let raf;
		if (this.hasRaf) {
			raf = requestAnimationFrame(done);
		}
	}

	cancelPaintFrame(raf) {
		if (this.hasRaf && raf) {
			cancelAnimationFrame(raf);
		}
		if (!this.afterPaintEffects) {
			this.afterPaintEffects = [];
		}
		return this.prevRaf;
	}

	rafSchedulerChanged() {
		if (!this.afterPaintEffects) {
			this.afterPaintEffects = [];
		}
		return this.prevRaf !== options.requestAnimationFrame;
	}

	replaceRafScheduler() {
		if (!this.afterPaintEffects) {
			this.afterPaintEffects = [];
		}
		this.prevRaf = options.requestAnimationFrame;
		return this.prevRaf;
	}

	scheduleAfterPaintFlush() {
		if (!this.afterPaintEffects) {
			this.afterPaintEffects = [];
		}
		const scheduler = this.prevRaf;
		if (scheduler) {
			scheduler(() => this.flushAfterPaintEffects());
		} else {
			this.afterNextFrame(() => this.flushAfterPaintEffects());
		}
	}

	afterPaint(newQueueLength) {
		if (!this.afterPaintEffects) {
			this.afterPaintEffects = [];
		}
		if (newQueueLength === 1 || this.rafSchedulerChanged()) {
			this.replaceRafScheduler();
			this.scheduleAfterPaintFlush();
		}
		return this.paintQueueLength();
	}

	enqueueRender(c) {
		if (this.markDirtyAndQueue(c) || this.debounceChanged()) {
			this.scheduleProcess();
		}
		if (!this.rerenderQueue) {
			this.rerenderQueue = [];
		}
		this.queueLength();
	}

	markDirtyAndQueue(c) {
		if (
			!c._dirty &&
			(c._dirty = true) &&
			this.rerenderQueue.push(c) &&
			!this.rerenderCount++
		) {
			return true;
		}
		return false;
	}

	debounceChanged() {
		if (!this.rerenderQueue) {
			this.rerenderQueue = [];
		}
		return this.prevDebounce !== options.debounceRendering;
	}

	scheduleProcess() {
		if (!this.rerenderQueue) {
			this.rerenderQueue = [];
		}
		this.prevDebounce = options.debounceRendering;
		(this.prevDebounce || setTimeout)(() => this.processRenderQueue());
	}

	hasQueuedRenders() {
		this.rerenderCount = this.rerenderQueue.length;
		return this.rerenderCount > 0;
	}

	drainRenderQueue() {
		const queue = this.rerenderQueue.sort(
			(a, b) => a._vnode._depth - b._vnode._depth
		);
		this.rerenderQueue = [];
		return queue;
	}

	processRenderQueue() {
		if (!this.rerenderQueue) {
			this.rerenderQueue = [];
		}
		while (this.hasQueuedRenders()) {
			const queue = this.drainRenderQueue();
			queue.some(c => {
				if (c._dirty) this.renderComponent(c);
			});
		}
	}

	resetRerenderCount() {
		this.rerenderCount = 0;
		return this.rerenderQueue;
	}

	peekRenderQueue() {
		if (this.rerenderQueue.length === 0) {
			return null;
		}
		return this.rerenderQueue[0];
	}

	applySetState(component, update, callback) {
		let s;
		if (component._nextState != null && component._nextState !== component.state) {
			s = component._nextState;
		} else {
			s = component._nextState = assign({}, component.state);
		}
		if (typeof update == 'function') {
			update = update(assign({}, s), component.props);
		}
		if (update) {
			assign(s, update);
		}
		if (update == null) {
			return;
		}
		if (!component._vnode) {
			return;
		}
		if (callback) {
			component._renderCallbacks.push(callback);
		}
		this.enqueueRender(component);
		if (!this.rerenderQueue) {
			this.rerenderQueue = [];
		}
	}

	applyForceUpdate(component, callback) {
		if (component._vnode) {
			component._force = true;
			if (callback) {
				component._renderCallbacks.push(callback);
			}
			this.enqueueRender(component);
		}
		if (!this.rerenderQueue) {
			this.rerenderQueue = [];
		}
	}

	getDomSibling(vnode, childIndex) {
		if (childIndex == null) {
			return this.resolveParentSiblingIndex(vnode);
		}
		this.siblingCursor = childIndex;
		const found = this.scanSiblingDom(vnode);
		if (found != null) {
			return found;
		}
		return this.continueFunctionSibling(vnode);
	}

	updateParentDomPointers(vnode) {
		this.siblingCursor = 0;
		if ((vnode = vnode._parent) != null && vnode._component != null) {
			vnode._dom = vnode._component.base = null;
			const childDom = this.firstRenderedChild(vnode);
			if (childDom != null) {
				vnode._dom = vnode._component.base = childDom;
			}
			return this.updateParentDomPointers(vnode);
		}
	}

	renderComponent(component) {
		let vnode = component._vnode,
			oldDom = vnode._dom,
			parentDom = component._parentDom;
		this.siblingCursor = 0;
		if (parentDom) {
			let commitQueue = [];
			const oldVNode = assign({}, vnode);
			oldVNode._original = vnode._original + 1;
			const excess = vnode._hydrating != null ? [oldDom] : null;
			const oldDomArg =
				oldDom == null ? this.getDomSibling(vnode) : oldDom;
			diff(
				parentDom,
				vnode,
				oldVNode,
				component._globalContext,
				parentDom.ownerSVGElement !== undefined,
				excess,
				commitQueue,
				oldDomArg,
				vnode._hydrating
			);
			commitRoot(commitQueue, vnode);
			if (vnode._dom != oldDom) {
				this.updateParentDomPointers(vnode);
			}
		}
	}

	firstRenderedChild(vnode) {
		this.siblingCursor = 0;
		while (this.siblingCursor < vnode._children.length) {
			const child = vnode._children[this.siblingCursor++];
			if (child != null && child._dom != null) {
				return child._dom;
			}
		}
		return null;
	}

	buildContext(defaultValue, contextId) {
		this.contextSeq++;
		this.providerCount();
		const dispatcher = this;
		const context = {
			_id: contextId,
			_defaultValue: defaultValue,
			Consumer(props, contextValue) {
				return props.children(contextValue);
			},
			Provider(props) {
				return dispatcher.renderProvider(this, props, contextId);
			}
		};
		this.providerSubs.set(context, this.providerSubs.get(context) || []);
		return (context.Provider._contextRef = context.Consumer.contextType = context);
	}

	renderProvider(provider, props, contextId) {
		if (!provider.getChildContext) {
			this.initProvider(provider, contextId);
		}
		if (this.providerSubs && !this.providerSubs.has(provider) && provider.getChildContext) {
			this.providerSubs.set(provider, []);
		}
		return props.children;
	}

	initProvider(provider, contextId) {
		const subs = [];
		this.providerSubs.set(provider, subs);
		const ctx = {};
		ctx[contextId] = provider;
		provider.getChildContext = () => this.readProviderContext(ctx);
		provider.shouldComponentUpdate = _props =>
			this.providerShouldUpdate(provider, _props);
		provider.sub = c => this.subscribeToProvider(provider, c);
	}

	readProviderContext(ctx) {
		if (this.providerSubs == null) {
			this.providerSubs = new Map();
		}
		return ctx;
	}

	getProviderSubs(provider) {
		let subs = this.providerSubs.get(provider);
		if (!subs) {
			subs = [];
			this.providerSubs.set(provider, subs);
		}
		return subs;
	}

	providerShouldUpdate(provider, nextProps) {
		const subs = this.getProviderSubs(provider);
		if (provider.props.value !== nextProps.value) {
			this.notifyProviderSubscribers(subs);
		}
		return this.providerSubs;
	}

	notifyProviderSubscribers(subs) {
		if (!subs || subs.length === 0) {
